  1311  /*-
  1312   * set the active key on an endpoint
  1313   * ASSUMES INP_WLOCK is already held
  1314   */
  1315  int
  1316  sctp_auth_setactivekey_ep(struct sctp_inpcb *inp, uint16_t keyid)
  1317  {
  1318          sctp_sharedkey_t *skey;
  1319
  1320          /* find the key */
  1321          skey = sctp_find_sharedkey(&inp->sctp_ep.shared_keys, keyid);
  1322          if (skey == NULL) {
  1323                  /* that key doesn't exist */
  1324                  return (-1);
  1325          }
  1326          inp->sctp_ep.default_keyid = keyid;
  1327          return (0);
  1328  }
