  1330  /*-
  1331   * deactivates a shared key from the association
  1332   * ASSUMES INP_WLOCK is already held
  1333   */
  1334  int
  1335  sctp_deact_sharedkey(struct sctp_tcb *stcb, uint16_t keyid)
  1336  {
  1337          sctp_sharedkey_t *skey;
  1338
  1339          if (stcb == NULL)
  1340                  return (-1);
  1341
  1342          /* is the keyid the assoc active sending key */
  1343          if (keyid == stcb->asoc.authinfo.active_keyid)
  1344                  return (-1);
  1345
  1346          /* does the key exist? */
  1347          skey = sctp_find_sharedkey(&stcb->asoc.shared_keys, keyid);
  1348          if (skey == NULL)
  1349                  return (-1);
  1350
  1351          /* are there other refcount holders on the key? */
  1352          if (skey->refcount == 1) {
  1353                  /* no other users, send a notification for this key */
  1354                  sctp_ulp_notify(SCTP_NOTIFY_AUTH_FREE_KEY, stcb, keyid, 0,
  1355                                  SCTP_SO_LOCKED);
  1356          }
  1357
  1358          /* mark the key as deactivated */
  1359          skey->deactivated = 1;
  1360
  1361          return (0);
  1362  }
